/* Test-only pinned libxml2 tree oracle. No Xemele runtime linkage. */
#include <stdio.h>
#include <stdlib.h>
#include <libxml/HTMLparser.h>
#include <libxml/tree.h>
static void string(const xmlChar *s) {putchar('"');if(s)for(;*s;s++){switch(*s){case '"':fputs("\\\"",stdout);break;case '\\':fputs("\\\\",stdout);break;case '\n':fputs("\\n",stdout);break;case '\r':fputs("\\r",stdout);break;case '\t':fputs("\\t",stdout);break;default:if(*s<32)printf("\\u%04x",*s);else putchar(*s);}}putchar('"');}
static void node(xmlNode *n){printf("{\"kind\":");string(BAD_CAST(n->type==XML_ELEMENT_NODE?"Element":n->type==XML_COMMENT_NODE?"Comment":n->type==XML_DTD_NODE?"DocumentType":"Text"));printf(",\"name\":");string(n->type==XML_ELEMENT_NODE||n->type==XML_DTD_NODE?n->name:BAD_CAST"");printf(",\"value\":");string(n->type==XML_TEXT_NODE||n->type==XML_CDATA_SECTION_NODE||n->type==XML_COMMENT_NODE?n->content:BAD_CAST"");if(n->type==XML_DTD_NODE){xmlDtd *d=(xmlDtd*)n;printf(",\"public\":");if(d->ExternalID)string(d->ExternalID);else fputs("null",stdout);printf(",\"system\":");if(d->SystemID)string(d->SystemID);else fputs("null",stdout);}printf(",\"attributes\":[");if(n->type==XML_ELEMENT_NODE){int first=1;for(xmlAttr *a=n->properties;a;a=a->next){if(!first)putchar(',');first=0;xmlChar *v=xmlNodeListGetString(n->doc,a->children,1);printf("[");string(a->name);putchar(',');string(v);putchar(']');xmlFree(v);}}printf("],\"children\":[");if(n->type==XML_ELEMENT_NODE){int first=1;for(xmlNode*c=n->children;c;c=c->next){if(!first)putchar(',');first=0;node(c);}}printf("]}");}
int main(int argc,char **argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");if(!f)return 2;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);char *b=malloc(n+1);if(fread(b,1,n,f)!=(size_t)n)return 2;b[n]=0;fclose(f);htmlDocPtr d=htmlReadMemory(b,n,NULL,NULL,HTML_PARSE_NODEFDTD|HTML_PARSE_NOERROR|HTML_PARSE_NOWARNING|HTML_PARSE_NONET);if(!d){puts("[]");free(b);return 0;}putchar('[');int first=1;for(xmlNode*c=d->children;c;c=c->next){if(!first)putchar(',');first=0;node(c);}puts("]");xmlFreeDoc(d);free(b);return 0;}
